head.script:
scwin.screenId = "jldfil58001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "img_44", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_46", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_48", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_50", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_52", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_53", fn: function(){ return (!(((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_38", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_20", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_22", entity: "dlt_bbsList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("contnTitle")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("regDdtm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("contnContn")); } }, { childId: "__rc3", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldfil58001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil58001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_FileDown_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_FileDown_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_FileDown_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fileDown('' + dlt_bbsList.getCellData(0, "contnId") + '','' + dlt_bbsList.getCellData(0, "contnAttachSeq") + '','' + dlt_bbsList.getCellData(0, "attachFileNm") + '','' + dlt_bbsList.getCellData(0, "regDdtm") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil58001.btn_FileDown_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_goList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil58001.btn_goList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goList = async function () {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: "/listInvstg/bbs.do",
        ref: "dma_goListReq",
        target: "dlt_bbsList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil58001.tx_fn_goList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/listInvstg/filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = async function () {
    /* sdd-asis-lifecycle:begin fn_goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.PdsViewForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchPdsList');
    { const nr = await scwin.tx_fn_goList(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil58000/jldfil58000.xml", { "method": 'searchPdsList' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnAttachSeq attachFileNm regDdtm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, contnAttachSeq, attachFileNm, regDdtm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.PdsViewForm || { elements: [] });
    frm.action = 'filedown.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchListInvstgBbsFile');
    $c.util.getComponent('dma_goListReq').set('contnId', contnId);
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_goListReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_goListReq').set('listInvstgBbsTpCd', '2');
    $c.util.getComponent('dma_goListReq').set('regDdtm', regDdtm);
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};
